// C 沒有內建雜湊表：把索引依數值排序後用雙指標
// 時間複雜度: O(n log n)，空間複雜度: O(n)
static int* g_nums;

static int cmpIdx(const void* a, const void* b) {
    int x = g_nums[*(const int*)a], y = g_nums[*(const int*)b];
    return (x > y) - (x < y);
}

int* twoSum(int* nums, int numsSize, int target, int* returnSize) {
    int* idx = malloc(sizeof(int) * numsSize);
    for (int i = 0; i < numsSize; i++) idx[i] = i;
    g_nums = nums;
    qsort(idx, numsSize, sizeof(int), cmpIdx);    // 排序索引，保留原始位置

    int* ans = malloc(sizeof(int) * 2);
    *returnSize = 0;
    int left = 0, right = numsSize - 1;
    while (left < right) {
        long sum = (long)nums[idx[left]] + nums[idx[right]];
        if (sum == target) {
            ans[0] = idx[left];
            ans[1] = idx[right];
            *returnSize = 2;
            break;
        }
        if (sum < target) left++;
        else right--;
    }
    free(idx);
    return ans;
}
